  /*
   * ar_app_ok()
   *	check if the last volume in the archive allows appends. We cannot check
   *	this until we are ready to write since there is no spec that says all
   *	volumes in a single archive have to be of the same type...
   * Return:
   *	0 if we can append, -1 otherwise.
   */

  func ar_app_ok() -> Result {
    if (artyp == .ISPIPE) {
      Tty.paxwarn(true, "Cannot append to an archive obtained from a pipe.");
      return .failed
    }

    if (!invld_rec) {
      return .ok
    }
    Tty.paxwarn(true,"Cannot append, device record size \(rdblksz) does not support \(programName) spec")
    return .failed
